 for(const m of messages){totals.set(m.sender_id,(totals.get(m.sender_id)||0)+1);for(const recipient of m.recipients){const pair=[m.sender_id,recipient].sort(),key=pair.join(':');edges.set(key,{a:pair[0],b:pair[1],n:(edges.get(key)?.n||0)+1});}}
